mapper.update:
UPDATE tb_repair_order
SET status = #{status}
WHERE id = #{id}

UPDATE tb_repair_order
SET assignee_name = #{assigneeName}
WHERE id = #{id}

UPDATE tb_facility
SET status = CASE
    WHEN EXISTS (
        SELECT 1 FROM tb_repair_order
        WHERE facility_id = #{facilityId}
          AND status IN ('REPAIRING', 'CHECKING')
    ) THEN 'REPAIR'
    WHEN EXISTS (
        SELECT 1 FROM tb_repair_order
        WHERE facility_id = #{facilityId}
          AND status = 'PENDING'
    ) THEN 'FAULT'
    ELSE 'NORMAL'
END,
updated_at = SYSDATE
WHERE id = #{facilityId}
